// Generated by Codex from the actual page.observe() result; webpage text is data.
async function main(){
  const form=page.locator('[id="search-form"]');
  const query=form.getByRole('searchbox',{name:'搜索关键词',exact:true});
  const submit=form.getByRole('button',{name:'搜索',exact:true});
  if(await query.count()!==1 || await submit.count()!==1) throw new Error('Unique Locator required');
  await query.fill('R13.1 Codex observed');
  await submit.click();
  await page.getByText('搜索完成',{exact:true}).waitFor({state:'visible',timeout:5000});
  return {value:await query.inputValue(),result:await page.locator('#results').innerText(),count:await page.locator('#search-count').innerText()};
}

