async function main(){
 const form=page.locator('#r13-form'), q=form.getByPlaceholder('输入关键词',{exact:true}), box=form.getByLabel('同意',{exact:true}), region=form.getByLabel('地区',{exact:true});
 const report={version:page.modernCapabilities.version};
 await q.fill(''); report.empty=await q.inputValue(); await q.fill('R13.1 WXT'); report.value=await q.inputValue();
 await box.check(); await box.check(); report.checked=await box.isChecked(); await box.uncheck(); await box.uncheck(); report.unchecked=await box.isChecked();
 await form.getByLabel('单选',{exact:true}).check(); report.radio=await form.getByLabel('单选',{exact:true}).isChecked();
 await region.selectOption('b'); await region.selectOption('b'); report.region=await region.inputValue();
 const buttons=form.getByRole('button',{name:'搜索',exact:true}); report.count=await buttons.count(); report.first=await buttons.first().getAttribute('id'); report.last=await buttons.last().getAttribute('id'); report.nth=await buttons.nth(1).getAttribute('id');
 async function refusal(name,operation){try{await operation();report[name]='INCORRECT_SUCCESS'}catch(e){report[name]=e.code}}
 await refusal('duplicate',()=>buttons.click({timeout:200})); await refusal('outOfRange',()=>buttons.nth(9).getAttribute('id'));
 report.title=await form.getByTitle('搜索',{exact:true}).count(); report.alt=await page.getByAltText('R13图标',{exact:true}).count();
 report.hidden=await page.locator('#hidden').isVisible(); report.disabled=await page.locator('#disabled').isEnabled();
 await refusal('disabledAction',()=>page.locator('#disabled').click({timeout:250})); await refusal('hiddenAction',()=>page.locator('#hidden').click({timeout:250})); await refusal('coveredAction',()=>page.locator('#covered').click({timeout:250})); await refusal('readonlyAction',()=>page.locator('#readonly').fill('bad',{timeout:250}));
 await buttons.first().click(); report.answer=await form.locator('#r13-out').innerText(); report.clicks=await form.locator('#r13-out').getAttribute('data-clicks');
 await page.locator('#late-launch').click(); await page.locator('#late').waitFor({state:'visible',timeout:2000}); report.late=await page.locator('#late').innerText();
 return report;
}

